"""mpl_toolkits.axisartist.parasite_axes — re-export of axes_grid1 parasite axes."""

from mpl_toolkits.axes_grid1.parasite_axes import SubplotHost, parasite_axes_class_factory


# HostAxes / ParasiteAxes live in the axisartist package's __init__.py
# but get re-exported through this submodule so user code can do
# ``from mpl_toolkits.axisartist.parasite_axes import HostAxes``.
def __getattr__(name):
    if name in ('HostAxes', 'ParasiteAxes'):
        from mpl_toolkits.axisartist import HostAxes, ParasiteAxes
        return {'HostAxes': HostAxes, 'ParasiteAxes': ParasiteAxes}[name]
    raise AttributeError(name)


__all__ = ['SubplotHost', 'parasite_axes_class_factory',
           'HostAxes', 'ParasiteAxes']
